{"policy":"permit (
    principal is User,
    action == Action::"viewPage",
    resource is Page
)
when {
    (
        principal.roles.contains(Role::"Reader") ||
        principal.roles.contains(Role::"Contributor") ||
        principal.roles.contains(Role::"Reviewer") ||
        principal.roles.contains(Role::"SpaceAdmin")
    ) &&
    (
        principal.clearance >= resource.classification ||
        resource.author == principal
    )
};

forbid (
    principal is User,
    action == Action::"viewPage",
    resource is Page
)
when {
    resource.status == "archived"
};"}
